  -- 2. Habilitar lançamento e permissão operacional em todas as contas (journal_account_rules)
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'journal_account_rules') THEN
    INSERT INTO journal_account_rules (company_id, account_code, active, posting_allowed)
    SELECT v_company_id, id, true, true
    FROM ledger_accounts
    WHERE company_id = v_company_id
    ON CONFLICT (company_id, account_code) DO UPDATE SET
      active = true,
      posting_allowed = true;
  END IF;

  -- 3. Atualizar a revisão contábil
  UPDATE accounting_revision
  SET revision = revision + 1
  WHERE company_id = v_company_id;

  RAISE NOTICE 'Total de 91 contas contábeis cadastradas/atualizadas com sucesso para a empresa %!', v_company_id;
